  function pick(arr) {
    return arr[Math.floor(Math.random() * arr.length)];
  }

  function detectMood(text) {
    if (!text) return 'general';
    for (const [mood, regex] of Object.entries(MOOD_PATTERNS)) {
      if (regex.test(text)) return mood;
    }
    return 'general';
  }

